// Bundles web/app/src into ONE classic script that the payload build injects into <head>.
//   node tools/bundle.mjs            write ../layers/01-app.js
//   node tools/bundle.mjs --verify   exit 1 if ../layers/01-app.js is not exactly what the sources produce
// The output is deterministic (pinned esbuild version, no timestamps), so --verify is a real
// freshness check: a hand edit to the generated file, or a source edit without a rebundle, fails.
import { build } from 'esbuild';
import { readFileSync, writeFileSync, readdirSync, statSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const APP = join(HERE, '..');
const OUT = join(APP, '..', 'layers', '01-app.js');
const CSS_OUT = join(APP, '..', 'buildlib', 'generated', 'dlapp.css');
const NAV_OUT = join(APP, '..', 'buildlib', 'generated', 'nav.html');
// The first legacy script. The bundle must be defined before any legacy code can call it.
const ANCHOR = '"use strict";const CG="https://api.coingecko.com/api/v3"';

function srcFiles(dir) {
  return readdirSync(dir).flatMap(n => {
    const p = join(dir, n);
    return statSync(p).isDirectory() ? srcFiles(p) : /\.(ts|md)$/.test(p) ? [p] : [];   // .md = blog content
  }).sort();
}

const h = createHash('sha256');
for (const f of srcFiles(join(APP, 'src'))) { h.update(relative(APP, f).split('\\').join('/')); h.update('\0'); h.update(readFileSync(f)); h.update('\0'); }
const srcSha = h.digest('hex');

const r = await build({
  entryPoints: [join(APP, 'src', 'index.ts')],
  bundle: true, write: false, format: 'iife', platform: 'browser', target: 'es2019',
  minify: true, legalComments: 'none', charset: 'utf8', logLevel: 'silent', loader: { '.md': 'text' },
});
const code = r.outputFiles[0].text.trim();
if (code.includes('</script')) throw new Error('bundle contains </script — it would terminate its own <script> tag');

const text = [
  '//@inject-before: ' + ANCHOR,
  '/* GENERATED by web/app/tools/bundle.mjs from web/app/src — DO NOT EDIT. Edit the TypeScript and rebundle.',
  '   sources sha256 ' + srcSha + ' */',
  code,
  '',
].join('\n');

// The stylesheet the design system emits (tokens first, then component classes). Built by
// running src/design/stylesheet.ts once in node — the same code that types the tokens.
const cssMod = await build({ entryPoints: [join(APP, 'src', 'design', 'stylesheet.ts')], bundle: true, write: false, format: 'esm', platform: 'node', logLevel: 'silent' });
const { stylesheet, navMarkup } = await import('data:text/javascript;base64,' + Buffer.from(cssMod.outputFiles[0].text).toString('base64'));
const css = '/* GENERATED by web/app/tools/bundle.mjs from web/app/src/design — DO NOT EDIT. sources ' + srcSha.slice(0, 12) + ' */\n' + stylesheet() + '\n';
if (css.includes('</style')) throw new Error('stylesheet contains </style');
const nav = navMarkup('markets') + '\n';

if (process.argv.includes('--verify')) {
  const read = f => { try { return readFileSync(f, 'utf8'); } catch { return ''; } };
  if (read(OUT) !== text) { console.error('✗ layers/01-app.js is stale or hand-edited — run: node web/app/tools/bundle.mjs'); process.exit(1); }
  if (read(CSS_OUT) !== css) { console.error('✗ buildlib/generated/dlapp.css is stale or hand-edited — run: node web/app/tools/bundle.mjs'); process.exit(1); }
  if (read(NAV_OUT) !== nav) { console.error('✗ buildlib/generated/nav.html is stale or hand-edited — run: node web/app/tools/bundle.mjs'); process.exit(1); }
  console.log('✓ layers/01-app.js and buildlib/generated/* are exactly what web/app/src produces (' + srcSha.slice(0, 12) + ')');
} else {
  mkdirSync(dirname(CSS_OUT), { recursive: true });
  writeFileSync(OUT, text); writeFileSync(CSS_OUT, css); writeFileSync(NAV_OUT, nav);
  console.log('bundled ' + (text.length / 1024).toFixed(1) + ' KB → layers/01-app.js, ' + (css.length / 1024).toFixed(1) + ' KB → buildlib/generated/dlapp.css (sources ' + srcSha.slice(0, 12) + ')');
}
